def calculate_metrics(df, group_by_columns=None):
    """计算指定分组的五个指标"""
    if group_by_columns is None or len(group_by_columns) == 0:
        # 如果是叶子节点（单个记录）
        return {
            'count': len(df),
            'sum_amount': df['amount'].sum() if 'amount' in df.columns else 0,
            'avg_amount': df['amount'].mean() if 'amount' in df.columns and len(df) > 0 else 0,
            'stdev_amount': df['amount'].std() if 'amount' in df.columns and len(df) > 1 else 0,
            'records': df.to_dict('records') if len(df) > 0 else []
        }
    else:
        # 计算分组指标
        grouped = df.groupby(group_by_columns)

        # 基本指标
        result = {}
        for name, group in grouped:
            if isinstance(name, tuple) and len(name) > 1:
                key = '|'.join([str(x) if x is not None else 'NULL' for x in name])
            else:
                key = str(name) if name is not None else 'NULL'

            result[key] = {
                'count': len(group),
                'sum_amount': group['amount'].sum() if 'amount' in group.columns else 0,
                'avg_amount': group['amount'].mean() if 'amount' in group.columns and len(group) > 0 else 0,
                'stdev_amount': group['amount'].std() if 'amount' in group.columns and len(group) > 1 else 0,
                'subgroups': {}
            }

            # 计算每个分组的top-3子段（按金额）
            if len(group_by_columns) < len(hierarchy):
                next_level = hierarchy[len(group_by_columns)]
                if next_level in group.columns:
                    # 按下一级分组计算金额总和，取top-3
                    next_grouped = group.groupby(next_level)['amount'].sum().sort_values(ascending=False)
                    top_3 = next_grouped.head(3)
                    result[key]['top_3_subsegments'] = {
                        segment: float(amount) for segment, amount in top_3.items()
                    }

        return result

def recursive_drill(df, level_index=0, current_path=None):
    """递归钻取数据"""
    if current_path is None:
        current_path = []

    if level_index >= len(hierarchy):
        # 到达叶子节点（单个记录）
        return {
            'level': 'individual_record',
            'path': current_path,
            'metrics': calculate_metrics(df),
            'children': None
        }

    current_level = hierarchy[level_index]

    # 检查当前层级是否存在
    if current_level not in df.columns:
        print(f"警告: 列 '{current_level}' 不存在，跳过此层级")
        # 跳过不存在的层级，继续下一层
        return recursive_drill(df, level_index + 1, current_path)

    # 按当前层级分组
    result = {
        'level': current_level,
        'path': current_path.copy(),
        'metrics': calculate_metrics(df, hierarchy[:level_index + 1]),
        'children': {}
    }

    # 对每个分组进行递归钻取
    grouped = df.groupby(current_level)
    for name, group in grouped:
        group_name = str(name) if name is not None else 'NULL'
        new_path = current_path + [f"{current_level}:{group_name}"]

        # 递归钻取下一层
        result['children'][group_name] = recursive_drill(group, level_index + 1, new_path)

    return result

