    # 简化结果以便序列化（避免DataFrame对象）
    def simplify_result(result):
        simplified = {}
        for key, value in result.items():
            if key == 'metrics':
                if isinstance(value, dict):
                    # 转换metrics中的值
                    simplified_metrics = {}
                    for metric_key, metric_value in value.items():
