                            }
                        elif isinstance(metric_value, (pd.DataFrame, pd.Series)):
                            # 跳过DataFrame/Series对象
                            continue
                        else:
                            # 转换数值类型
                            try:
                                simplified_metrics[metric_key] = float(metric_value) if not isinstance(metric_value, (str, list, dict)) else metric_value
                            except:
                                simplified_metrics[metric_key] = metric_value
                    simplified[key] = simplified_metrics
            elif key == 'children':
                if value is None:
                    simplified[key] = None
                else:
                    simplified_children = {}
                    for child_key, child_value in value.items():
                        simplified_children[child_key] = simplify_result(child_value)
                    simplified[key] = simplified_children
            else:
                simplified[key] = value
        return simplified

