# 定义计算函数
def calculate_summary(df, group_cols, level_name):
    """计算指定层级的摘要信息"""
    if group_cols and all(col in df.columns for col in group_cols):
        grouped = df.groupby(group_cols)
        summary = grouped.agg({
            'amount': ['count', 'sum', 'mean', 'std']
        }).reset_index()

        # 重命名列
        summary.columns = ['_'.join(filter(None, col)).strip('_') for col in summary.columns.values]

        # 计算top-3子段
        if level_name != 'individual_record':
            # 找出下一层级
            if hierarchy.index(group_cols[0]) + 1 < len(hierarchy):
                next_level = hierarchy[hierarchy.index(group_cols[0]) + 1]
                if next_level in df.columns:
                    top_3_list = []
                    for group_name in summary[f"{group_cols[0]}"].unique():
                        group_data = df[df[group_cols[0]] == group_name]
                        if next_level in group_data.columns:
                            top_subsegments = group_data.groupby(next_level)['amount'].sum().nlargest(3)
                            top_3_list.append({
                                'group': group_name,
                                'top_3': top_subsegments.to_dict()
                            })

        return summary
    else:
        return pd.DataFrame()

